-- Generated by DbStudio from Oracle. Parameters (:NAME) are prompted for when you run a statement.

-- Registered customers
-- SHOP.CUSTOMERS: UPDATE
UPDATE SHOP.CUSTOMERS
SET
    NAME = :NAME,
    EMAIL = :EMAIL,
    COUNTRY_ID = :COUNTRY_ID
WHERE ID = :ID;

-- SHOP.ORDERS: UPDATE
UPDATE SHOP.ORDERS
SET
    CUSTOMER_ID = :CUSTOMER_ID,
    ORDER_DATE = :ORDER_DATE,
    TOTAL = :TOTAL
WHERE ID = :ID;

-- SHOP.ORDER_LINES: UPDATE
UPDATE SHOP.ORDER_LINES
SET
    QTY = :QTY
WHERE ORDER_ID = :ORDER_ID
  AND PRODUCT_ID = :PRODUCT_ID;

-- SHOP.PRODUCTS: UPDATE
UPDATE SHOP.PRODUCTS
SET
    NAME = :NAME,
    PRICE = :PRICE
WHERE ID = :ID;

-- SHOP.COUNTRIES: UPDATE
UPDATE SHOP.COUNTRIES
SET
    NAME = :NAME
WHERE ID = :ID;

-- Issued invoices
-- SHOP.INVOICES: UPDATE
UPDATE SHOP.INVOICES
SET
    CUSTOMER_ID = :CUSTOMER_ID,
    ISSUED_AT = :ISSUED_AT,
    AMOUNT = :AMOUNT,
    PAID = :PAID,
    NOTES = :NOTES,
    PDF = :PDF,
    DUE_IN = :DUE_IN
WHERE INVOICE_ID = :INVOICE_ID;
